const assets = {"/index.html": "<!doctype html>\n<html lang=\"en\">\n<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"theme-color\" content=\"#eef4f2\"><meta name=\"description\" content=\"A three-act cultural exchange for two curious people.\"><title>TasteTrail / Sidequests</title><link rel=\"stylesheet\" href=\"/style.css\"><script defer src=\"/app.js\"></script></head>\n<body><div class=\"app-shell\">\n  <header class=\"topbar\"><a class=\"brand\" href=\"/\" aria-label=\"TasteTrail Sidequests home\"><span class=\"brand-symbol\" aria-hidden=\"true\">✳</span><span>taste<span>trail</span><small>sidequests</small></span></a><div class=\"top-right\"><span class=\"top-note\">A little adventure for two</span><span class=\"connection\" id=\"connection-status\">Checking connection</span></div></header>\n  <main><div class=\"heading\"><div><p class=\"overline\">A mixtape for two curious minds</p><h1>Trade tastes.<br>Find a new favorite.</h1></div><p>Bring one thing each of you loves. We’ll make a three-part cultural sidequest you can explore together.</p></div>\n    <div class=\"workspace\">\n      <aside class=\"setup\" aria-labelledby=\"setup-title\"><div class=\"setup-heading\"><span class=\"mini-mark\" aria-hidden=\"true\">✳</span><div><h2 id=\"setup-title\">Set the scene</h2><p>Choose one starting point each.</p></div></div>\n        <div class=\"seed-stack\">\n          <section class=\"seed seed-a\" aria-labelledby=\"seed-a-title\"><div class=\"seed-title\"><span class=\"seed-letter\">A</span><div><h3 id=\"seed-a-title\">Person one</h3><p>What are you into?</p></div></div><form class=\"search-form\" id=\"search-a\"><label for=\"query-a\">An artist, film, book, or show</label><div class=\"search-row\"><input id=\"query-a\" name=\"query\" maxlength=\"100\" placeholder=\"e.g. Radiohead\" required autocomplete=\"off\"><button type=\"submit\">Search</button></div></form><div id=\"search-results-a\" class=\"search-results\" aria-live=\"polite\"></div></section>\n          <section class=\"seed seed-b\" aria-labelledby=\"seed-b-title\"><div class=\"seed-title\"><span class=\"seed-letter\">B</span><div><h3 id=\"seed-b-title\">Person two</h3><p>What do they love?</p></div></div><form class=\"search-form\" id=\"search-b\"><label for=\"query-b\">An artist, film, book, or show</label><div class=\"search-row\"><input id=\"query-b\" name=\"query\" maxlength=\"100\" placeholder=\"e.g. Björk\" required autocomplete=\"off\"><button type=\"submit\">Search</button></div></form><div id=\"search-results-b\" class=\"search-results\" aria-live=\"polite\"></div></section>\n        </div>\n        <fieldset class=\"style-picker\"><legend>Choose your route</legend><label><input type=\"radio\" name=\"style\" value=\"meet\" checked><span><strong>Meet in the middle</strong><small>Look for shared ground first</small></span></label><label><input type=\"radio\" name=\"style\" value=\"exchange\"><span><strong>Trade worlds</strong><small>Explore each other’s tastes</small></span></label></fieldset>\n        <button class=\"primary-button\" id=\"make-plan\" type=\"button\" disabled>Make our sidequest <span aria-hidden=\"true\">↗</span></button><p class=\"setup-footnote\">Suggestions are a starting point, not a prediction of what you’ll like.</p>\n      </aside>\n      <section class=\"programme\" aria-labelledby=\"programme-title\"><div class=\"programme-head\"><div><p class=\"programme-kicker\">Your three-part programme</p><h2 id=\"programme-title\">The sidequest</h2></div><div class=\"programme-actions\"><span id=\"mode-badge\" class=\"mode-badge\" hidden></span><button id=\"export-plan\" class=\"text-button\" type=\"button\" disabled>Export plan ↓</button></div></div>\n        <div id=\"plan-message\" class=\"plan-message\" role=\"status\">Search and select a starting point for both people to make your programme.</div>\n        <div id=\"programme-cards\" class=\"programme-cards\" aria-live=\"polite\"><div class=\"empty-card\"><span>01</span><div><strong>Listen</strong><p>A sound to discover together.</p></div><span class=\"empty-star\" aria-hidden=\"true\">✳</span></div><div class=\"empty-card\"><span>02</span><div><strong>Watch</strong><p>A story for your screen.</p></div><span class=\"empty-star\" aria-hidden=\"true\">✳</span></div><div class=\"empty-card\"><span>03</span><div><strong>Read</strong><p>A page into a new world.</p></div><span class=\"empty-star\" aria-hidden=\"true\">✳</span></div></div>\n        <div class=\"programme-footer\"><p id=\"revision-label\">Ready when you are.</p><button id=\"repair-all\" class=\"secondary-button\" type=\"button\" disabled>Rethink unlocked acts ↻</button></div>\n        <details class=\"trace-panel\" id=\"trace-panel\"><summary>How this was made <span>View steps +</span></summary><p>Each step below is a recorded tool operation for this programme. Rankings describe returned lists, not the reasons behind a person’s taste.</p><ol id=\"trace-list\"></ol></details>\n      </section>\n    </div>\n  </main><footer><span>taste<span>trail</span> / sidequests</span><p>Made for two. Powered by Qloo when connected.</p><span>Listen · Watch · Read</span></footer>\n</div></body></html>\n", "/style.css": "@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,500;9..144,600&display=swap');\n:root{--ink:#1d3040;--muted:#5b6d74;--paper:#eef4f2;--line:#cbd8d3;--serif:'Fraunces',Georgia,serif;--sans:'DM Sans',Arial,sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.5 var(--sans)}button,input{font:inherit}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.45}a{color:inherit}.app-shell{max-width:1500px;padding:0 5%;margin:auto}.topbar{height:86px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{text-decoration:none;font-weight:700;font-size:22px;line-height:.8;display:flex;gap:9px;align-items:center;letter-spacing:-1px}.brand>span:nth-child(2)>span{color:#3d796e}.brand small{display:block;font-size:9px;letter-spacing:.13em;font-weight:700;text-transform:uppercase;margin-top:8px}.brand-symbol{font-size:35px;font-weight:400;color:#e97b63}.top-right{display:flex;align-items:center;gap:20px}.top-note{font-size:13px;color:var(--muted)}.connection,.mode-badge{border:1px solid #bfcec9;border-radius:99px;padding:7px 11px;font-weight:600;font-size:12px}.connection:before{content:'';display:inline-block;width:7px;height:7px;border-radius:50%;background:#d89d55;margin-right:7px}.connection.configured:before{background:#4e957e}.heading{display:flex;justify-content:space-between;align-items:end;gap:40px;padding:50px 0 35px}.overline,.programme-kicker{font-size:12px;font-weight:700;letter-spacing:.04em;color:#467b70;margin:0 0 9px}h1,h2,h3,p{margin-top:0}h1,h2{font-family:var(--serif);font-weight:500;letter-spacing:-.045em}h1{font-size:clamp(43px,5vw,70px);line-height:1.04;margin:0}.heading>p{max-width:365px;font-size:16px;color:var(--muted);margin:0 0 6px}.workspace{display:grid;grid-template-columns:minmax(300px,385px) minmax(0,1fr);gap:24px;align-items:start}.setup{background:#fff;border:1px solid #dbe5e0;border-radius:8px;padding:26px}.setup-heading{display:flex;gap:13px;align-items:center;margin-bottom:23px}.mini-mark{font-size:27px;color:#db755e}.setup-heading h2{font:600 23px var(--serif);letter-spacing:-.03em;margin:0}.setup-heading p,.seed-title p{font-size:13px;color:var(--muted);margin:3px 0 0}.seed-stack{display:grid;gap:12px}.seed{border-radius:6px;padding:17px}.seed-a{background:#e2f2eb}.seed-b{background:#feebe5}.seed-title{display:flex;align-items:center;gap:10px;margin-bottom:15px}.seed-letter{width:34px;height:34px;display:grid;place-items:center;background:#fff;border-radius:50%;font-weight:700;color:#377365}.seed-b .seed-letter{color:#b35b48}.seed-title h3{font-size:14px;margin:0}.search-form label{display:block;font-size:12px;font-weight:600;margin-bottom:7px}.search-row{display:flex;background:#fff;border:1px solid transparent;border-radius:4px;overflow:hidden}.search-row:focus-within{border-color:#407f72}.search-row input{width:100%;min-width:0;padding:10px 10px;border:0;outline:0;background:transparent}.search-row input::placeholder{color:#9aa9a7}.search-row button{border:0;background:transparent;color:#326b60;font-weight:700;font-size:12px;padding:0 11px}.search-results{font-size:12px}.search-results:not(:empty){margin-top:10px}.search-message{color:#536b66;margin:0}.search-message.error{color:#a53432}.choices{display:grid;gap:5px}.choice{background:#fff;border:1px solid transparent;text-align:left;padding:9px;border-radius:3px;color:var(--ink);display:flex;align-items:center;gap:9px;width:100%}.choice:hover,.choice.selected{border-color:#407f72}.choice img{height:32px;width:32px;object-fit:cover;border-radius:3px}.choice strong,.choice small{display:block}.choice small{font-size:11px;color:var(--muted)}.chosen{display:flex;justify-content:space-between;align-items:center;gap:10px;background:#fff;padding:9px;border-radius:3px}.chosen strong{font-size:13px}.chosen small{display:block;color:var(--muted)}.chosen button{border:0;background:transparent;color:#397466;font-weight:700;font-size:11px}.style-picker{border:0;padding:0;margin:24px 0}.style-picker legend{font-weight:700;margin-bottom:11px}.style-picker label{display:flex;align-items:start;gap:9px;margin:10px 0;cursor:pointer}.style-picker input{accent-color:#407d70;margin-top:4px}.style-picker strong,.style-picker small{display:block}.style-picker strong{font-size:13px}.style-picker small{font-size:12px;color:var(--muted)}.primary-button{width:100%;background:var(--ink);color:#fff;border:0;border-radius:4px;text-align:left;padding:15px 17px;font-weight:700}.primary-button span{float:right}.setup-footnote{font-size:12px;color:var(--muted);margin:13px 0 0}.programme{background:#d9eae2;border-radius:8px;padding:28px;min-width:0}.programme-head{display:flex;justify-content:space-between;align-items:start;gap:14px}.programme-head h2{font-size:36px;line-height:1.1;margin:0}.programme-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;justify-content:end}.text-button{background:transparent;border:0;border-bottom:1px solid var(--ink);padding:4px 0;color:var(--ink);font-size:12px;font-weight:700}.mode-badge{background:#fff8d9;border-color:#decf96;color:#765820}.mode-badge.live{background:#f4fbf7;color:#356d5c;border-color:#accdc0}.plan-message{font-size:13px;color:#526b61;margin:18px 0;max-width:700px}.plan-message.error{color:#a53532}.programme-cards{display:grid;gap:10px}.empty-card,.act{background:#fff;border-radius:5px;display:grid;grid-template-columns:52px minmax(0,1fr) auto;gap:16px;padding:20px;align-items:center}.empty-card>span:first-child,.act-index{font:500 15px var(--serif);color:#789288}.empty-card strong{font:500 24px var(--serif)}.empty-card p{font-size:13px;color:#85978f;margin:2px 0 0}.empty-star{font-size:27px;color:#dfebe5}.act{align-items:start;grid-template-columns:38px minmax(80px,105px) minmax(0,1fr);gap:14px;padding:16px}.act-image{width:100%;aspect-ratio:1;object-fit:cover;border-radius:3px;background:#e4efea}.act-image-placeholder{width:100%;aspect-ratio:1;display:grid;place-items:center;border-radius:3px;background:#e4efea;color:#93b6a8;font-size:34px}.act:nth-child(2) .act-image-placeholder{background:#ffebe4;color:#edab96}.act:nth-child(3) .act-image-placeholder{background:#f8f0d3;color:#d0b45d}.act-content{min-width:0}.act-top{display:flex;justify-content:space-between;gap:10px;align-items:center}.act-kind{font-size:11px;font-weight:700;color:#477b6f}.lane{font-size:11px;font-weight:700;padding:4px 8px;background:#e6f1eb;border-radius:99px;white-space:nowrap}.lane.from_a{background:#e3f4ed}.lane.from_b{background:#fce8e0}.act h3{font:500 clamp(20px,2.1vw,27px)/1.15 var(--serif);letter-spacing:-.03em;margin:8px 0}.act-description,.act-evidence{font-size:12px;color:#60746b;margin:5px 0;overflow-wrap:anywhere}.act-evidence{color:#3f5b50}.rank-row{font-size:11px;font-weight:700;color:#52766a;margin-top:8px}.act-controls{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:12px}.act-controls button{border:1px solid #cbd9d2;background:#fff;border-radius:99px;padding:6px 10px;color:var(--ink);font-size:11px;font-weight:700}.act-controls button.locked{background:#244e43;color:#fff;border-color:#244e43}.act-unavailable{grid-column:2 / -1;color:var(--muted);font-size:13px}.act-unavailable strong{display:block;font:500 23px var(--serif);color:var(--ink);margin-bottom:4px}.programme-footer{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:20px 0}.programme-footer p{font-size:12px;color:#4d6c60;margin:0}.secondary-button{border:1px solid #8dad9e;border-radius:4px;padding:10px 14px;color:#27554a;background:transparent;font-size:12px;font-weight:700}.trace-panel{border-top:1px solid #abc8ba;padding-top:16px}.trace-panel summary{cursor:pointer;font-size:13px;font-weight:700;display:flex;justify-content:space-between;list-style:none}.trace-panel summary::-webkit-details-marker{display:none}.trace-panel summary span{font-size:12px;color:#4f7b6e}.trace-panel>p{font-size:12px;color:#5b7569;max-width:660px;margin:12px 0}.trace-panel ol{padding:0;margin:0;list-style:none;display:grid;gap:7px}.trace-panel li{font-size:12px;background:#f2faf5;padding:9px 12px;display:flex;justify-content:space-between;gap:10px}.trace-panel li span:last-child{color:#628376;white-space:nowrap}footer{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:36px 0;font-size:12px;color:#667b72}footer>span:first-child{font-weight:700;font-size:14px;color:var(--ink)}footer>span:first-child span{color:#40796b}footer p{margin:0}:focus-visible{outline:3px solid #d06d57;outline-offset:3px}\n@media(max-width:850px){.workspace{grid-template-columns:1fr}.heading{align-items:start}.setup{padding:22px}.seed-stack{grid-template-columns:1fr 1fr}.programme{padding:22px}}@media(max-width:600px){.app-shell{padding:0 4%}.topbar{height:72px}.top-note{display:none}.heading{display:block;padding:36px 0 25px}.heading>p{margin-top:18px}.seed-stack{grid-template-columns:1fr}.programme{padding:18px}.programme-head h2{font-size:30px}.programme-actions{display:grid;justify-items:end}.act{grid-template-columns:25px 70px minmax(0,1fr);padding:14px;gap:10px}.act h3{font-size:20px}.act-top{align-items:start;flex-direction:column}.programme-footer{align-items:start;flex-direction:column}footer{align-items:start;flex-direction:column;gap:8px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\n@media(max-width:600px){.act{grid-template-columns:25px minmax(0,1fr)}.act>.act-image,.act>.act-image-placeholder{grid-column:2;width:82px}.act-content{grid-column:1 / -1}.act-top{flex-direction:row;align-items:center}.act-description,.act-evidence{font-size:13px;line-height:1.55}.rank-row{line-height:1.6}.trace-panel li{display:block}.trace-panel li span{display:block}.trace-panel li span:last-child{white-space:normal;margin-top:4px}}\n", "/app.js": "'use strict';\n\nconst selections = {a: null, b: null};\nconst searchTraces = {a: [], b: []};\nlet current = null;\nlet busy = false;\nconst $ = (selector) => document.querySelector(selector);\nconst makeButton = $('#make-plan');\nconst repairButton = $('#repair-all');\nconst exportButton = $('#export-plan');\nconst cards = $('#programme-cards');\nconst planMessage = $('#plan-message');\nconst modeBadge = $('#mode-badge');\n\nfunction el(tag, className, content) {\n  const element = document.createElement(tag);\n  if (className) element.className = className;\n  if (content !== undefined) element.textContent = content;\n  return element;\n}\n\nfunction imageUrl(value) {\n  try {\n    const url = new URL(value);\n    return url.protocol === 'https:' ? url.href : null;\n  } catch { return null; }\n}\n\nfunction updateControls() {\n  document.querySelectorAll('.setup input, .setup button').forEach(control => { control.disabled = busy; });\n  makeButton.disabled = busy || !selections.a || !selections.b;\n  exportButton.disabled = busy || !current;\n  repairButton.disabled = busy || !current || !current.plan.some(item => !item.locked);\n  document.querySelectorAll('.act-controls button').forEach(button => { button.disabled = busy || button.dataset.lockedSkip === 'true'; });\n}\n\nfunction setMessage(value, error = false) {\n  planMessage.textContent = value || '';\n  planMessage.classList.toggle('error', error);\n  planMessage.hidden = !value;\n}\n\nfunction invalidatePlan() {\n  if (!current) return;\n  current = null;\n  modeBadge.hidden = true;\n  cards.replaceChildren();\n  for (const [number, label, detail] of [['01', 'Listen', 'A sound to discover together.'], ['02', 'Watch', 'A story for your screen.'], ['03', 'Read', 'A page into a new world.']]) {\n    const card = el('div', 'empty-card');\n    const inner = el('div'); inner.append(el('strong', '', label), el('p', '', detail));\n    const star = el('span', 'empty-star', '✳'); star.setAttribute('aria-hidden', 'true');\n    card.append(el('span', '', number), inner, star); cards.append(card);\n  }\n  $('#revision-label').textContent = 'Ready when you are.';\n  $('#trace-list').replaceChildren();\n  setMessage('Your starting points changed. Make a new sidequest.');\n  updateControls();\n}\n\nasync function post(url, payload) {\n  let response;\n  try { response = await fetch(url, {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(payload)}); }\n  catch { throw new Error('Could not reach the server. Check the connection and try again.'); }\n  let body;\n  try { body = await response.json(); }\n  catch { throw new Error('The server returned an unreadable response. Try again.'); }\n  if (!response.ok) throw new Error(body.error || 'The request could not be completed. Try again.');\n  return body;\n}\n\nfunction showSearchMessage(side, text, error = false) {\n  const result = $(`#search-results-${side}`);\n  result.replaceChildren(el('p', `search-message${error ? ' error' : ''}`, text));\n}\n\nfunction selectedView(side, entity, mode) {\n  const result = $(`#search-results-${side}`);\n  const selected = el('div', 'chosen');\n  const content = el('div');\n  content.append(el('strong', '', entity.name), el('small', '', [entity.type.replace(/^urn:entity:/, '').replaceAll('_', ' '), typeof entity.disambiguation === 'string' ? entity.disambiguation : '', mode === 'demo' ? 'synthetic example' : ''].filter(Boolean).join(' · ')));\n  const change = el('button', '', 'Change'); change.type = 'button';\n  change.addEventListener('click', () => { selections[side] = null; result.replaceChildren(); invalidatePlan(); updateControls(); $(`#query-${side}`).focus(); });\n  selected.append(content, change); result.replaceChildren(selected);\n}\n\nfor (const side of ['a', 'b']) {\n  const form = $(`#search-${side}`);\n  form.addEventListener('submit', async event => {\n    event.preventDefault();\n    const query = form.elements.query.value.trim();\n    if (!query || busy) return;\n    selections[side] = null; invalidatePlan();\n    busy = true; updateControls(); showSearchMessage(side, 'Searching for a starting point…');\n    try {\n      const data = await post('/api/search', {query});\n      if (!Array.isArray(data.entities) || !['live', 'demo'].includes(data.mode)) throw new Error('The search returned an unexpected response.');\n      searchTraces[side] = Array.isArray(data.trace) ? data.trace : [];\n      const result = $(`#search-results-${side}`); result.replaceChildren();\n      if (data.mode === 'demo') result.append(el('p', 'search-message', 'Synthetic examples, not Qloo results.'));\n      if (data.warning) result.append(el('p', 'search-message', data.warning));\n      if (!data.entities.length) result.append(el('p', 'search-message', 'No matches found. Try another name.'));\n      else {\n        result.append(el('p', 'search-message', 'Select the right match:'));\n        const choices = el('div', 'choices');\n        data.entities.forEach(entity => {\n          if (!entity || typeof entity.id !== 'string' || typeof entity.name !== 'string' || typeof entity.type !== 'string') return;\n          const choice = el('button', 'choice'); choice.type = 'button';\n          const url = imageUrl(entity.image);\n          if (url) { const img = el('img'); img.src = url; img.alt = ''; img.loading = 'lazy'; img.referrerPolicy = 'no-referrer'; img.addEventListener('error', () => img.remove(), {once: true}); choice.append(img); }\n          const content = el('span'); content.append(el('strong', '', entity.name), el('small', '', [entity.type.replace(/^urn:entity:/, '').replaceAll('_', ' '), typeof entity.disambiguation === 'string' ? entity.disambiguation : ''].filter(Boolean).join(' · '))); choice.append(content);\n          choice.addEventListener('click', () => { selections[side] = {id: entity.id, name: entity.name, type: entity.type}; selectedView(side, entity, data.mode); updateControls(); }); choices.append(choice);\n        });\n        result.append(choices);\n      }\n    } catch (error) { showSearchMessage(side, error.message, true); }\n    finally { busy = false; updateControls(); }\n  });\n  form.elements.query.addEventListener('input', () => {\n    if (selections[side]) { selections[side] = null; $(`#search-results-${side}`).replaceChildren(); invalidatePlan(); updateControls(); }\n  });\n}\n\nconst actNames = {artist: ['01', 'Listen'], movie: ['02', 'Watch'], book: ['03', 'Read']};\nconst lanes = {shared: 'Shared ground', from_a: 'From person one', from_b: 'From person two'};\n\nfunction artwork(item) {\n  const url = imageUrl(item.image);\n  if (!url) return el('div', 'act-image-placeholder', '✳');\n  const img = el('img', 'act-image'); img.src = url; img.alt = ''; img.loading = 'lazy'; img.referrerPolicy = 'no-referrer';\n  img.addEventListener('error', () => img.replaceWith(el('div', 'act-image-placeholder', '✳')), {once: true});\n  return img;\n}\n\nfunction renderPlan(data) {\n  current = data;\n  modeBadge.hidden = false; modeBadge.className = `mode-badge ${data.mode}`;\n  modeBadge.textContent = data.mode === 'live' ? 'Live Qloo results' : 'Synthetic example';\n  setMessage(data.warning || (data.mode === 'demo' ? 'Synthetic example: not Qloo results or predictions.' : ''));\n  cards.replaceChildren();\n  for (const item of data.plan) {\n    const [number, title] = actNames[item.slot] || ['', item.slot || 'Explore'];\n    const card = el('article', 'act'); card.append(el('span', 'act-index', number));\n    if (item.unavailable || !item.id) {\n      const empty = el('div', 'act-unavailable'); empty.append(el('strong', '', title), el('span', '', item.description || 'No candidate is available for this act.')); if (item.evidence) empty.append(el('p', 'act-evidence', item.evidence));\n      const controls = el('div', 'act-controls'); const retry = el('button', '', 'Retry this act'); retry.type = 'button'; retry.addEventListener('click', () => repair([], [item.slot])); controls.append(retry); empty.append(controls); card.append(empty); cards.append(card); continue;\n    }\n    card.append(artwork(item));\n    const content = el('div', 'act-content'); const top = el('div', 'act-top');\n    top.append(el('span', 'act-kind', title), el('span', `lane ${item.lane || ''}`, lanes[item.lane] || 'Discovery')); content.append(top);\n    content.append(el('h3', '', item.name || 'Untitled'));\n    if (item.description) content.append(el('p', 'act-description', item.description));\n    if (item.evidence) content.append(el('p', 'act-evidence', item.evidence));\n    if (item.ranks) {\n      const rank = n => Number.isFinite(n) ? `#${n}` : 'not in returned list';\n      content.append(el('p', 'rank-row', `Person one: ${rank(item.ranks.a)}  ·  Person two: ${rank(item.ranks.b)}`));\n    }\n    const controls = el('div', 'act-controls');\n    const lock = el('button', item.locked ? 'locked' : '', item.locked ? '✓ Locked' : 'Lock this act'); lock.type = 'button'; lock.setAttribute('aria-pressed', item.locked ? 'true' : 'false');\n    lock.addEventListener('click', () => { item.locked = !item.locked; renderPlan(current); });\n    const skip = el('button', '', 'Swap this act'); skip.type = 'button';\n    skip.disabled = Boolean(item.locked); skip.title = item.locked ? 'Unlock this act before swapping it' : 'Find another candidate for this act';\n    skip.dataset.lockedSkip = String(Boolean(item.locked));\n    skip.addEventListener('click', () => repair([item.id], [item.slot]));\n    controls.append(lock, skip); content.append(controls); card.append(content); cards.append(card);\n  }\n  $('#revision-label').textContent = `Programme ${data.revision} · ${data.style === 'exchange' ? 'Trade worlds' : 'Meet in the middle'}`;\n  const traceList = $('#trace-list'); traceList.replaceChildren();\n  const traces = [...searchTraces.a, ...searchTraces.b, ...(Array.isArray(data.trace) ? data.trace : [])];\n  if (!traces.length) traceList.append(el('li', '', 'No tool steps were returned.'));\n  traces.forEach(trace => { const li = el('li'); li.append(el('span', '', `${trace.label || trace.tool || 'Step'}${trace.tool ? ` (${trace.tool})` : ''}`), el('span', '', `${trace.status || 'unknown'}${Number.isFinite(trace.elapsedMs) ? ` · ${trace.elapsedMs} ms` : ''}`)); traceList.append(li); });\n  updateControls();\n}\n\nfunction style() { return document.querySelector('input[name=\"style\"]:checked').value; }\nfunction validPlan(data) { return data && ['live', 'demo'].includes(data.mode) && typeof data.sessionId === 'string' && Array.isArray(data.plan); }\n\nmakeButton.addEventListener('click', async () => {\n  if (busy || !selections.a || !selections.b) return;\n  busy = true; updateControls(); setMessage('Building your three-part programme…');\n  try {\n    const data = await post('/api/plan', {a: selections.a, b: selections.b, style: style()});\n    if (!validPlan(data)) throw new Error('The programme response was incomplete. Try again.');\n    renderPlan(data);\n  } catch (error) { setMessage(error.message, true); }\n  finally { busy = false; updateControls(); if (current) { const visibleError = planMessage.classList.contains('error') ? planMessage.textContent : null; renderPlan(current); if (visibleError) setMessage(visibleError, true); } }\n});\n\nasync function repair(rejected = [], replaceSlots = []) {\n  if (busy || !current) return;\n  busy = true; updateControls(); setMessage('Finding another route…');\n  try {\n    const locked = current.plan.filter(item => item.locked && item.id).map(item => item.id);\n    const payload = {sessionId: current.sessionId, locked, rejected, style: style()};\n    if (replaceSlots.length) payload.replaceSlots = replaceSlots;\n    const data = await post('/api/repair', payload);\n    if (!validPlan(data)) throw new Error('The revised programme response was incomplete. Try again.');\n    renderPlan(data);\n  } catch (error) { setMessage(error.message, true); }\n  finally { busy = false; updateControls(); if (current) { const visibleError = planMessage.classList.contains('error') ? planMessage.textContent : null; renderPlan(current); if (visibleError) setMessage(visibleError, true); } }\n}\nrepairButton.addEventListener('click', () => repair());\n\nexportButton.addEventListener('click', () => {\n  if (!current) return;\n  const copy = {...current, trace: [...searchTraces.a, ...searchTraces.b, ...(current.trace || [])]};\n  const blob = new Blob([JSON.stringify(copy, null, 2)], {type: 'application/json'});\n  const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'tastetrail-sidequest.json'; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);\n});\n\nfetch('/api/status').then(response => { if (!response.ok) throw new Error(); return response.json(); }).then(data => {\n  const status = $('#connection-status'); status.textContent = data.configured ? 'Qloo key configured' : 'Synthetic example mode'; status.classList.toggle('configured', Boolean(data.configured));\n}).catch(() => { $('#connection-status').textContent = 'Connection unavailable'; });\n", "/": "<!doctype html>\n<html lang=\"en\">\n<head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><meta name=\"theme-color\" content=\"#eef4f2\"><meta name=\"description\" content=\"A three-act cultural exchange for two curious people.\"><title>TasteTrail / Sidequests</title><link rel=\"stylesheet\" href=\"/style.css\"><script defer src=\"/app.js\"></script></head>\n<body><div class=\"app-shell\">\n  <header class=\"topbar\"><a class=\"brand\" href=\"/\" aria-label=\"TasteTrail Sidequests home\"><span class=\"brand-symbol\" aria-hidden=\"true\">✳</span><span>taste<span>trail</span><small>sidequests</small></span></a><div class=\"top-right\"><span class=\"top-note\">A little adventure for two</span><span class=\"connection\" id=\"connection-status\">Checking connection</span></div></header>\n  <main><div class=\"heading\"><div><p class=\"overline\">A mixtape for two curious minds</p><h1>Trade tastes.<br>Find a new favorite.</h1></div><p>Bring one thing each of you loves. We’ll make a three-part cultural sidequest you can explore together.</p></div>\n    <div class=\"workspace\">\n      <aside class=\"setup\" aria-labelledby=\"setup-title\"><div class=\"setup-heading\"><span class=\"mini-mark\" aria-hidden=\"true\">✳</span><div><h2 id=\"setup-title\">Set the scene</h2><p>Choose one starting point each.</p></div></div>\n        <div class=\"seed-stack\">\n          <section class=\"seed seed-a\" aria-labelledby=\"seed-a-title\"><div class=\"seed-title\"><span class=\"seed-letter\">A</span><div><h3 id=\"seed-a-title\">Person one</h3><p>What are you into?</p></div></div><form class=\"search-form\" id=\"search-a\"><label for=\"query-a\">An artist, film, book, or show</label><div class=\"search-row\"><input id=\"query-a\" name=\"query\" maxlength=\"100\" placeholder=\"e.g. Radiohead\" required autocomplete=\"off\"><button type=\"submit\">Search</button></div></form><div id=\"search-results-a\" class=\"search-results\" aria-live=\"polite\"></div></section>\n          <section class=\"seed seed-b\" aria-labelledby=\"seed-b-title\"><div class=\"seed-title\"><span class=\"seed-letter\">B</span><div><h3 id=\"seed-b-title\">Person two</h3><p>What do they love?</p></div></div><form class=\"search-form\" id=\"search-b\"><label for=\"query-b\">An artist, film, book, or show</label><div class=\"search-row\"><input id=\"query-b\" name=\"query\" maxlength=\"100\" placeholder=\"e.g. Björk\" required autocomplete=\"off\"><button type=\"submit\">Search</button></div></form><div id=\"search-results-b\" class=\"search-results\" aria-live=\"polite\"></div></section>\n        </div>\n        <fieldset class=\"style-picker\"><legend>Choose your route</legend><label><input type=\"radio\" name=\"style\" value=\"meet\" checked><span><strong>Meet in the middle</strong><small>Look for shared ground first</small></span></label><label><input type=\"radio\" name=\"style\" value=\"exchange\"><span><strong>Trade worlds</strong><small>Explore each other’s tastes</small></span></label></fieldset>\n        <button class=\"primary-button\" id=\"make-plan\" type=\"button\" disabled>Make our sidequest <span aria-hidden=\"true\">↗</span></button><p class=\"setup-footnote\">Suggestions are a starting point, not a prediction of what you’ll like.</p>\n      </aside>\n      <section class=\"programme\" aria-labelledby=\"programme-title\"><div class=\"programme-head\"><div><p class=\"programme-kicker\">Your three-part programme</p><h2 id=\"programme-title\">The sidequest</h2></div><div class=\"programme-actions\"><span id=\"mode-badge\" class=\"mode-badge\" hidden></span><button id=\"export-plan\" class=\"text-button\" type=\"button\" disabled>Export plan ↓</button></div></div>\n        <div id=\"plan-message\" class=\"plan-message\" role=\"status\">Search and select a starting point for both people to make your programme.</div>\n        <div id=\"programme-cards\" class=\"programme-cards\" aria-live=\"polite\"><div class=\"empty-card\"><span>01</span><div><strong>Listen</strong><p>A sound to discover together.</p></div><span class=\"empty-star\" aria-hidden=\"true\">✳</span></div><div class=\"empty-card\"><span>02</span><div><strong>Watch</strong><p>A story for your screen.</p></div><span class=\"empty-star\" aria-hidden=\"true\">✳</span></div><div class=\"empty-card\"><span>03</span><div><strong>Read</strong><p>A page into a new world.</p></div><span class=\"empty-star\" aria-hidden=\"true\">✳</span></div></div>\n        <div class=\"programme-footer\"><p id=\"revision-label\">Ready when you are.</p><button id=\"repair-all\" class=\"secondary-button\" type=\"button\" disabled>Rethink unlocked acts ↻</button></div>\n        <details class=\"trace-panel\" id=\"trace-panel\"><summary>How this was made <span>View steps +</span></summary><p>Each step below is a recorded tool operation for this programme. Rankings describe returned lists, not the reasons behind a person’s taste.</p><ol id=\"trace-list\"></ol></details>\n      </section>\n    </div>\n  </main><footer><span>taste<span>trail</span> / sidequests</span><p>Made for two. Powered by Qloo when connected.</p><span>Listen · Watch · Read</span></footer>\n</div></body></html>\n"};
const randomUUID = () => crypto.randomUUID();

const categories = ['artist', 'movie', 'book'];
const seedTypes = [...categories, 'tv_show'];
const list = data => Array.isArray(data?.results) ? data.results : Array.isArray(data?.results?.entities) ? data.results.entities : [];
const id = item => String(item?.entity_id || item?.id || '');
const trim = value => typeof value === 'string' ? value.trim() : '';
function imageUrl(value) {
  try { const u = new URL(typeof value === 'string' ? value : value?.url); return u.protocol === 'https:' ? u.href : null; } catch { return null; }
}
function entity(item, fallback) {
  const types = [item.subtype, item.type, ...(Array.isArray(item.types) ? item.types : [])].filter(x => typeof x === 'string').map(x => x.split(':').at(-1));
  const type = types.find(x => seedTypes.includes(x)) || (seedTypes.includes(fallback) ? fallback : 'unknown');
  return { id: id(item), name: String(item.name || '').slice(0, 180), type,
    description: String(item.properties?.short_description || item.properties?.description || '').slice(0, 380), image: imageUrl(item.properties?.image),
    disambiguation: typeof item.disambiguation === 'string' ? item.disambiguation.slice(0, 200) : '' };
}
const warning = 'Qloo describes aggregate cultural affinity. List overlap and rank are evidence for discovery, not a prediction of what either person will enjoy. No availability, duration or streaming access is verified.';
const demoWarning = 'Illustrative fictional examples only. No Qloo request was made and these suggestions are not derived from your interests.';

function createPlanner({ request, configured, initialSession }) {
  const sessions = new Map();
  if (initialSession) { initialSession.rejected = new Set(initialSession.rejected); sessions.set(initialSession.id, initialSession); }
  async function tool(trace, name, label, path, params) {
    const start = Date.now();
    try { const data = await request(path, params); trace.push({ tool: name, label, status: 'complete', elapsedMs: Date.now() - start }); return data; }
    catch (error) { trace.push({ tool: name, label, status: 'error', elapsedMs: Date.now() - start }); throw error; }
  }
  async function search(body, trace = []) {
    const query = trim(body?.query);
    const type = body?.type;
    if (!query || query.length > 100 || (type && !seedTypes.includes(type))) throw new Error('Enter an artist, film, book or show name (up to 100 characters).');
    if (!configured) return { mode: 'demo', entities: [{ id: 'demo-a', name: 'Fictional starting point A', type: 'artist', description: 'An illustrative seed, not a real Qloo entity.' }, { id: 'demo-b', name: 'Fictional starting point B', type: 'movie', description: 'An illustrative seed, not a real Qloo entity.' }], trace, warning: demoWarning };
    const result = await tool(trace, 'qloo.search', `Find “${query}”`, '/search', { query, take: '12', types: (type ? [type] : seedTypes).map(s => `urn:entity:${s}`).join(',') });
    const entities = [...new Map(list(result).filter(x => id(x) && x.name).map(x => [id(x), entity(x, type)])).values()].filter(x => x.type !== 'unknown');
    return { mode: 'live', entities, trace, warning: entities.length ? 'Choose the intended entity before planning.' : 'No entities found. Try the original title or a different name.' };
  }
  async function confirm(seed, trace) {
    if (!seed || typeof seed.id !== 'string' || seed.id.length > 120 || !trim(seed.name)) throw new Error('Search and select one starting point for each person.');
    if (!configured) {
      if (!['demo-a', 'demo-b'].includes(seed.id)) throw new Error('Select one of the fictional example seeds.');
      return { id: seed.id, name: seed.id === 'demo-a' ? 'Fictional starting point A' : 'Fictional starting point B', type: seed.id === 'demo-a' ? 'artist' : 'movie', description: 'Illustrative seed.' };
    }
    const result = await search({ query: seed.name, type: seed.type }, trace);
    const match = result.entities.find(e => e.id === seed.id);
    if (!match) throw new Error('That starting point could not be confirmed. Search and select it again.');
    return match;
  }
  function prune() {
    const now = Date.now();
    for (const [key, value] of sessions) if (now - value.updated > 3_600_000) sessions.delete(key);
    if (sessions.size >= 100) sessions.delete(sessions.keys().next().value);
  }
  async function pools(slot, seeds, exclude, trace, revision) {
    if (!configured) {
      const sample = n => ({ entity_id: `demo-${slot}-${n}`, name: `Fictional ${slot === 'artist' ? 'artist' : slot} ${n}`, properties: { short_description: 'A synthetic placeholder for the cultural exchange flow.' } });
      return { a: [sample(revision * 4), sample(revision * 4 + 1)], b: [sample(revision * 4), sample(revision * 4 + 2)] };
    }
    const query = (seed, side) => tool(trace, 'qloo.insights', `${slot === 'artist' ? 'Music' : slot === 'movie' ? 'Film' : 'Book'} discoveries for person ${side}`, '/v2/insights', { 'filter.type': `urn:entity:${slot}`, 'signal.interests.entities': seed.id, take: '20', ...(exclude.size ? { 'filter.exclude.entities': [...exclude].join(',') } : {}) });
    const responses = await Promise.allSettled([query(seeds.a, 'A'), query(seeds.b, 'B')]);
    const failed = responses.find(x => x.status === 'rejected');
    if (failed) throw failed.reason;
    return { a: list(responses[0].value), b: list(responses[1].value) };
  }
  function choose(slot, pool, style, exclude) {
    const clean = items => [...new Map(items.filter(x => id(x) && x.name).map(x => [id(x), x])).values()];
    const a = clean(pool.a), b = clean(pool.b);
    const ar = new Map(a.map((x, n) => [id(x), n + 1])), br = new Map(b.map((x, n) => [id(x), n + 1]));
    const shared = a.filter(x => br.has(id(x))).sort((x, y) => ar.get(id(x)) + br.get(id(x)) - ar.get(id(y)) - br.get(id(y)));
    const fromA = a.filter(x => !br.has(id(x))), fromB = b.filter(x => !ar.has(id(x)));
    const desired = style === 'exchange' ? (slot === 'artist' ? 'from_a' : slot === 'movie' ? 'from_b' : 'shared') : 'shared';
    const lanes = desired === 'from_a' ? [[fromA, 'from_a'], [shared, 'shared'], [fromB, 'from_b']] : desired === 'from_b' ? [[fromB, 'from_b'], [shared, 'shared'], [fromA, 'from_a']] : [[shared, 'shared'], [fromA, 'from_a'], [fromB, 'from_b']];
    for (const [items, lane] of lanes) {
      const pick = items.find(x => !exclude.has(id(x)));
      if (!pick) continue;
      const ranks = { a: ar.get(id(pick)) || null, b: br.get(id(pick)) || null };
      return { ...entity(pick, slot), type: slot, slot, lane, ranks, locked: false,
        evidence: lane === 'shared' ? `Returned in both lists: A #${ranks.a}, B #${ranks.b}. Shared candidates are ordered by the sum of these positions.` : `Returned in ${lane === 'from_a' ? 'A' : 'B'}'s list at #${ranks.a || ranks.b}, outside the other returned list. An invitation to explore, not evidence of the other person's preference.` };
    }
    return { slot, type: slot, unavailable: true, locked: false, evidence: 'No unexcluded candidates were returned for this scene. Try different seeds or release an exclusion by starting a new mix.' };
  }
  async function compose({ seeds, style, previous = [], locked = new Set(), rejected = new Set(), replaceSlots = categories, trace, revision }) {
    const keptIds = previous.filter(x => x.id && (!replaceSlots.includes(x.slot) || locked.has(x.id))).map(x => x.id);
    const excluded = new Set([seeds.a.id, seeds.b.id, ...rejected, ...keptIds]);
    const plan = [];
    let success = 0;
    for (const slot of categories) {
      const kept = previous.find(x => x.slot === slot && (locked.has(x.id) || !replaceSlots.includes(slot)));
      if (kept) { plan.push({ ...kept, locked: locked.has(kept.id) }); trace.push({ tool: 'planner.keep', label: `Kept your ${locked.has(kept.id) ? 'locked ' : ''}${slot} scene`, status: 'complete', elapsedMs: 0 }); if (kept.id) success++; continue; }
      try {
        const pool = await pools(slot, seeds, excluded, trace, revision);
        success++;
        const pick = choose(slot, pool, style, excluded);
        plan.push(pick); if (pick.id) excluded.add(pick.id);
      } catch (error) {
        plan.push({ slot, type: slot, unavailable: true, locked: false, evidence: `This scene could not be retrieved. ${error.message}` });
      }
    }
    if (!success) throw new Error('Qloo could not retrieve any scenes. Check connection or credential and retry. No example results have been substituted.');
    trace.push({ tool: 'planner.compose', label: `Arranged ${plan.filter(x => x.id).length} scenes with your ${style === 'exchange' ? 'exchange' : 'shared discovery'} preference`, status: 'complete', elapsedMs: 0 });
    return plan;
  }
  const snapshot = session => ({ sessionId: session.id, revision: session.revision, mode: configured ? 'live' : 'demo', style: session.style, seeds: session.seeds, plan: session.plan, trace: session.trace, warning: configured ? warning : demoWarning });
  async function plan(body) {
    if (!body || !['meet', 'exchange'].includes(body.style)) throw new Error('Choose shared discovery or exchange mode.');
    const trace = [];
    const [a, b] = await Promise.all([confirm(body.a, trace), confirm(body.b, trace)]);
    const seeds = { a, b };
    const picks = await compose({ seeds, style: body.style, trace, revision: 1 });
    prune();
    const session = { id: randomUUID(), seeds, style: body.style, plan: picks, rejected: new Set(), trace, revision: 1, updated: Date.now(), busy: false };
    sessions.set(session.id, session);
    return snapshot(session);
  }
  async function repair(body) {
    const session = sessions.get(body?.sessionId);
    if (!session || Date.now() - session.updated > 3_600_000) throw new Error('This mix has expired or the server restarted. Create a new mix.');
    if (session.busy) throw new Error('This mix is already being updated. Wait for the current request.');
    if (session.revision >= 12) throw new Error('This mix reached its revision limit. Start a new mix to continue.');
    if (!Array.isArray(body.locked) || !Array.isArray(body.rejected) || body.locked.length > 3 || body.rejected.length > 3) throw new Error('Invalid scene selection.');
    const known = new Set(session.plan.filter(x => x.id).map(x => x.id));
    if ([...body.locked, ...body.rejected].some(x => typeof x !== 'string' || !known.has(x))) throw new Error('A selected scene does not belong to the current mix.');
    const locked = new Set(body.locked), rejected = new Set([...session.rejected, ...body.rejected]);
    if ([...locked].some(x => rejected.has(x))) throw new Error('A scene cannot be locked and skipped at the same time.');
    if (locked.size === categories.length) throw new Error('Unlock at least one scene to remix.');
    const replaceSlots = body.replaceSlots ?? categories;
    if (!Array.isArray(replaceSlots) || !replaceSlots.length || replaceSlots.some(x => !categories.includes(x))) throw new Error('Invalid scenes to replace.');
    for (const item of session.plan) if (item.id && !locked.has(item.id) && replaceSlots.includes(item.slot)) rejected.add(item.id);
    const style = body.style ?? session.style;
    if (!['meet', 'exchange'].includes(style)) throw new Error('Invalid discovery style.');
    session.busy = true;
    try {
      const trace = [];
      const picks = await compose({ seeds: session.seeds, style, previous: session.plan, locked, rejected, replaceSlots, trace, revision: session.revision + 1 });
      Object.assign(session, { style, plan: picks, rejected, trace, revision: session.revision + 1, updated: Date.now() });
      return snapshot(session);
    } finally { session.busy = false; }
  }
  return { search, plan, repair, getSession: sessionId => sessions.get(sessionId) };
}


const contentTypes = {'/':'text/html; charset=utf-8','/index.html':'text/html; charset=utf-8','/style.css':'text/css; charset=utf-8','/app.js':'text/javascript; charset=utf-8'};
const limits = new Map();
function tooMany(ip) { const now=Date.now(), key=ip||'unknown'; const current=(limits.get(key)||[]).filter(t=>now-t<60000); if(current.length>=20) return true; current.push(now); limits.set(key,current); if(limits.size>1000) for(const [k,v] of limits) if(now-v[v.length-1]>=60000) limits.delete(k); return false; }
function json(status, value) { return new Response(JSON.stringify(value), { status, headers: {'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff'} }); }
function b64(bytes) { return btoa(Array.from(bytes, c => String.fromCharCode(c)).join('')).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,''); }
function unb64(s) { const x=atob(s.replace(/-/g,'+').replace(/_/g,'/')); return Uint8Array.from(x, c => c.charCodeAt(0)); }
async function cipherKey(secret) { const hash = await crypto.subtle.digest('SHA-256', new TextEncoder().encode('TasteTrail session v1:' + secret)); return crypto.subtle.importKey('raw',hash,'AES-GCM',false,['encrypt','decrypt']); }
async function seal(session,secret) { const iv=crypto.getRandomValues(new Uint8Array(12)); const payload=JSON.stringify({...session,rejected:[...session.rejected],busy:false}); const enc=await crypto.subtle.encrypt({name:'AES-GCM',iv},await cipherKey(secret),new TextEncoder().encode(payload)); return b64(iv)+'.'+b64(new Uint8Array(enc)); }
async function openToken(token,secret) { try { if(typeof token!=='string'||token.length>40000) throw 0; const [a,b,...rest]=token.split('.'); if(!a||!b||rest.length) throw 0; const bytes=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(a)},await cipherKey(secret),unb64(b)); const obj=JSON.parse(new TextDecoder().decode(bytes)); if(!obj.id||!Array.isArray(obj.rejected)||!Array.isArray(obj.plan)||!Number.isFinite(obj.updated)||Date.now()-obj.updated>3600000) throw 0; return obj; } catch { throw new Error('This mix has expired or is invalid. Create a new mix.'); } }
function qloo(key) { let next=0; return async (path,params) => { const scheduled=Math.max(Date.now(),next); next=scheduled+260; if(scheduled>Date.now()) await new Promise(r=>setTimeout(r,scheduled-Date.now())); const url=new URL(path,'https://hackathon.api.qloo.com'); for(const [k,v] of Object.entries(params)) url.searchParams.set(k,v); let response; try { response=await fetch(url,{headers:{'X-Api-Key':key,Accept:'application/json'},signal:AbortSignal.timeout(25000),redirect:'error'}); } catch { throw new Error('Could not reach Qloo. Check network access and try again.'); } if(!response.ok) { if(response.status===401||response.status===403) throw new Error('Qloo rejected the API credential. Check the server configuration.'); if(response.status===429) throw new Error('Qloo rate limit reached. Please try again later.'); throw new Error(`Qloo returned an error (${response.status}). Please try again later.`); } const text=await response.text(); if(text.length>1000000) throw new Error('Qloo response exceeded the allowed size.'); let data; try { data=JSON.parse(text); } catch { throw new Error('Qloo returned an unreadable response.'); } if(data?.success===false) throw new Error('Qloo could not complete this request.'); return data; }; }
export default { async fetch(req,env) { const url=new URL(req.url), path=url.pathname, key=(env.QLOO_API_KEY || '').trim(); if(req.method==='GET'&&path==='/api/status') return json(200,{configured:Boolean(key),planner:'deterministic'}); if(req.method==='GET'&&assets[path]) return new Response(assets[path],{headers:{'content-type':contentTypes[path],'x-content-type-options':'nosniff','cache-control':'no-store'}}); if(req.method!=='POST'||!['/api/search','/api/plan','/api/repair'].includes(path)) return json(404,{error:'Not found.'}); if(tooMany(req.headers.get('cf-connecting-ip'))) return json(429,{error:'Too many requests. Please wait a minute.'}); try { const origin=req.headers.get('origin'); if(origin && origin!==url.origin) return json(403,{error:'Invalid request origin.'}); const raw=await req.text(); if(raw.length>50000) return json(413,{error:'Request is too large.'}); let body; try { body=JSON.parse(raw); } catch { throw new Error('Request must contain valid JSON.'); } if(!body||typeof body!=='object'||Array.isArray(body)) throw new Error('Request must contain a JSON object.'); const secret=key || 'fictional-demo-only'; let initialSession; if(path==='/api/repair') { initialSession=await openToken(body.sessionId,secret); body.sessionId=initialSession.id; } const planner=createPlanner({request:qloo(key),configured:Boolean(key),initialSession}); const result=await planner[path.slice(5)](body); if(path!=='/api/search') result.sessionId=await seal(planner.getSession(result.sessionId),secret); return json(200,result); } catch(e) { return json(400,{error:e.message||'Could not create the sidequest.'}); } } };
